func ptrAgentRun(p unsafe.Pointer, c int32) any {
	r := (*agent.AgentRun)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.AgentDefinitionID))
	case 4:
		return (*string)(unsafe.Pointer(&r.Trigger))
	case 5:
		return &r.Summary
	case 6:
		return (*string)(unsafe.Pointer(&r.AgentType))
	case 7:
		return (*string)(unsafe.Pointer(&r.SubjectType))
	case 8:
		return (*string)(unsafe.Pointer(&r.SubjectID))
	case 9:
		return (*string)(unsafe.Pointer(&r.Status))
	case 10:
		return &r.WorkflowID
	case 11:
		return &r.ModelIdentifier
	case 12:
		return &r.PromptVersion
	case 13:
		return &r.InputContextHash
	case 14:
		return &r.StartedAt
	case 15:
		return &r.CompletedAt
	case 16:
		return &r.ErrorMessage
	case 17:
		return &r.Tainted
	case 18:
		return &r.Taint
	case 19:
		return &r.TaintedAt
	case 20:
		return &r.Fingerprint
	case 21:
		return &r.Transcript
	case 22:
		return &r.TraceID
	case 23:
		return (*string)(unsafe.Pointer(&r.TurnID))
	case 24:
		return (*string)(unsafe.Pointer(&r.ParentOwnerKind))
	case 25:
		return (*string)(unsafe.Pointer(&r.ParentOwnerID))
	case 26:
		return &r.DelegateCallID
	case 27:
		return &r.Version
	case 28:
		return &r.CreatedAt
	case 29:
		return &r.UpdatedAt
	}
	return nil
}

func valueAgentRun(p unsafe.Pointer, c int32) any {
	r := (*agent.AgentRun)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		if r.AgentDefinitionID == "" {
			return nil
		}
		return string(r.AgentDefinitionID)
	case 4:
		return string(r.Trigger)
	case 5:
		if r.Summary == "" {
			return nil
		}
		return r.Summary
	case 6:
		return string(r.AgentType)
	case 7:
		return string(r.SubjectType)
	case 8:
		return string(r.SubjectID)
	case 9:
		return string(r.Status)
	case 10:
		if r.WorkflowID == "" {
			return nil
		}
		return r.WorkflowID
	case 11:
		if r.ModelIdentifier == "" {
			return nil
		}
		return r.ModelIdentifier
	case 12:
		return r.PromptVersion
	case 13:
		return r.InputContextHash
	case 14:
		if r.StartedAt == 0 {
			return nil
		}
		return r.StartedAt
	case 15:
		if r.CompletedAt == nil {
			return nil
		}
		return *r.CompletedAt
	case 16:
		if r.ErrorMessage == "" {
			return nil
		}
		return r.ErrorMessage
	case 17:
		return r.Tainted
	case 18:
		if r.Taint == nil {
			return nil
		}
		return *r.Taint
	case 19:
		if r.TaintedAt == nil {
			return nil
		}
		return *r.TaintedAt
	case 20:
		if r.Fingerprint == nil {
			return nil
		}
		return *r.Fingerprint
	case 21:
		if r.Transcript == nil {
			return nil
		}
		return *r.Transcript
	case 22:
		if r.TraceID == "" {
			return nil
		}
		return r.TraceID
	case 23:
		if r.TurnID == "" {
			return nil
		}
		return string(r.TurnID)
	case 24:
		if r.ParentOwnerKind == "" {
			return nil
		}
		return string(r.ParentOwnerKind)
	case 25:
		if r.ParentOwnerID == "" {
			return nil
		}
		return string(r.ParentOwnerID)
	case 26:
		if r.DelegateCallID == "" {
			return nil
		}
		return r.DelegateCallID
	case 27:
		return r.Version
	case 28:
		return r.CreatedAt
	case 29:
		return r.UpdatedAt
	}
	return nil
}

