var enumProposalStatus = [...]schema.EnumValue{
	{Value: `Pending`, Label: `Pending`},
	{Value: `Approving`, Label: `Approving`, Doc: `ProposalStatusApproving is an approval that has not gone through yet: approved from the person's own conversation, it commits a few seconds later unless they undo it first. It is neither waiting on anyone nor decided, so no queue lists it and no sweep expires it.`},
	{Value: `Accepted`, Label: `Accepted`},
	{Value: `Modified`, Label: `Modified`},
	{Value: `Rejected`, Label: `Rejected`},
	{Value: `Expired`, Label: `Expired`},
	{Value: `Superseded`, Label: `Superseded`},
	{Value: `Executed`, Label: `Executed`, Doc: `ProposalStatusExecuted and ProposalStatusExecutionFailed separate "a person approved this" from "the tool actually ran". Without them an accepted proposal is indistinguishable from a completed one, which is exactly the ambiguity that let accepted proposals go unexecuted unnoticed.`},
	{Value: `ExecutionFailed`, Label: `Execution Failed`},
	{Value: `Skipped`, Label: `Skipped`, Doc: `ProposalStatusSkipped is a plan step that never ran because a step before it failed. Nobody decided against it and it did not expire.`},
	{Value: `Simulated`, Label: `Simulated`, Doc: `ProposalStatusSimulated is a write that was cleared to run while its agent was in simulation: previewed and recorded, never made.`},
}

